sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float radius;
uniform float blades;
uniform float rotation;
uniform float hiCut;
uniform float highlightGain;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 acc = float4(0.0);
    float ws = 0.0;
    for (int i = 0; i < 32; i++) {
        float fi = float(i) + 0.5;
        float r = sqrt(fi / 32.0);
        float a = fi * 2.3999632 + radians(rotation);
        float shape = 1.0;
        if (blades >= 3.0) {
            float sector = 6.2831853 / blades;
            float am = mod(a, sector) - sector * 0.5;
            shape = cos(3.1415927 / blades) / cos(am);
        }
        float4 s4 = tex(coord + float2(cos(a), sin(a)) * r * shape * radius);
        float w = 1.0 + max(luma(unp(s4)) - hiCut, 0.0) * highlightGain * 4.0;
        acc += s4 * w;
        ws += w;
    }
    return fin(c, mix(c, acc / ws, amount), opacity);
}
